import { QUESTIONS } from './data.js';
import { calculate } from './calculator.js';
const fmt=value=>new Intl.NumberFormat('de-DE',{maximumFractionDigits:4}).format(value);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const range=r=>r.min===r.max?fmt(r.min):`${fmt(r.min)}–${fmt(r.max)}`;
const moduleNames=['Mobilität','Verstehen & Sprechen','Verhalten & Psyche','Selbstversorgung','Krankheit & Therapie','Alltag & Kontakte'];
const disclaimer='Dies ist eine unverbindliche Selbsteinschätzung. Der tatsächliche Pflegegrad wird durch die zuständige Pflegeversicherung auf Grundlage der Begutachtung festgestellt. Das Ergebnis kann von diesem Rechner abweichen.';
export function answerText(q,a){
  if(a==null)return 'Offen / unsicher';
  if(q.type==='choice')return `${q.options.find(o=>o.value===a)?.label||a} (${a} Punkte)`;
  if(q.type==='continence')return !a.eligible?'Voraussetzung nicht erfüllt (0 Punkte)':a.value==null?'Voraussetzung erfüllt, Selbstständigkeit offen':`${q.options.find(o=>o.value===a.value)?.label||a.value} (${a.value} Punkte)`;
  if(a.daily)return 'Täglich; 60 Rechenpunkte vor Gruppenbildung';
  return [['day','pro Tag'],['week','pro Woche'],['month','pro Monat']].filter(([key])=>a[key]>0).map(([key,label])=>`${a[key]} ${label}`).join(', ')||'Entfällt oder selbstständig';
}
function explanation(id){
  return {1:'Die fünf Kriterien erhalten jeweils 0 bis 3 Einzelpunkte. Die Summe wird über feste Stufen in maximal 10 gewichtete Punkte übertragen.',2:'Die elf Fähigkeiten werden mit jeweils 0 bis 3 Punkten bewertet. Es zählt ausschließlich der höhere gewichtete Wert aus Modul 2 oder 3; gemeinsam sind maximal 15 Punkte möglich.',3:'Die dreizehn Kriterien verwenden Häufigkeiten mit 0, 1, 3 oder 5 Punkten. Derselbe Unterstützungsvorgang darf nicht mehrfach verschiedenen Verhaltensweisen zugeordnet werden. Der gemeinsame Anteil mit Modul 2 beträgt höchstens 15 Punkte.',4:'Essen erhält 0/3/6/9 Punkte; Trinken und Toilettennutzung jeweils 0/2/4/6 Punkte. Inkontinenzkriterien gelten nur bei erfüllter Voraussetzung. Ernährung über Sonde oder venösen Zugang: entfällt/selbstständig 0, teilweise 6, vollständig 3 Punkte. Die Summe wird auf maximal 40 gewichtete Punkte übertragen.',5:'Die Frequenzen in 5.1–5.7 und 5.8–5.11 werden getrennt zusammengefasst: Woche ÷ 7, Monat ÷ 30. Die Gruppen werden getrennt bepunktet. Für 5.12–5.15 gelten besondere Faktoren. Anschließend wird 5.16 addiert. Die Summe von 0 bis 15 Einzelpunkten wird in maximal 20 gewichtete Punkte übertragen.',6:'Die sechs Kriterien erhalten jeweils 0 bis 3 Einzelpunkte. Die Summe wird in maximal 15 gewichtete Punkte übertragen. Außerhäusliche Aktivitäten und Haushaltsführung bilden keinen zusätzlichen Punkteanteil.'}[id];
}
export function resultPage(state){
  const r=calculate(state.answers,{adult:state.adult===true}),complete=r.complete;
  const gradeText=g=>g===0?'Kein Pflegegrad':`Pflegegrad ${g}`;
  const grade=r.grade.min===r.grade.max?gradeText(r.grade.min):r.grade.min===0?`Kein Pflegegrad bis Pflegegrad ${r.grade.max}`:`Pflegegrad ${r.grade.min}–${r.grade.max}`;
  const biggest=[r.modules[0],r.modules[3],r.modules[4],r.modules[5]].sort((a,b)=>b.weighted.min-a.weighted.min)[0];
  return `<div class="page result-page route-enter"><div class="print-only"><strong>Pflegekompass · Ihre Selbsteinschätzung</strong><p>Stand 11.11.2026 · Geltendes Recht · Erwachsene</p></div><div class="result-top"><p class="eyebrow"><span class="status-dot"></span> Ihre persönliche Orientierung</p><span class="result-status">${complete?'64 von 64 Kriterien beantwortet':`${r.missingIds.length} Kriterien noch offen`}</span></div>
    <div class="result-hero"><div><h1 class="sr-only">Ergebnis Ihrer Pflegegrad-Selbsteinschätzung</h1><div class="result-number ${!complete?'range':''}">${complete?fmt(r.total.min):`${fmt(r.total.min)}–${fmt(r.total.max)}`}</div><p class="result-unit">${complete?'gewichtete Punkte von 100':'Punkte · möglicher Bereich von 100'}</p></div><div><h2 class="result-grade">${grade}</h2><p class="result-summary">${complete?'Nach Ihren Angaben ergibt sich diese rechnerische Einstufung.':'Dies ist der rechnerisch mögliche Bereich. Ergänzen Sie die offenen Angaben für eine vollständige Selbsteinschätzung.'} Die fachliche Begutachtung und weitere gesetzliche Voraussetzungen bleiben entscheidend.</p></div></div>
    <div class="result-actions"><button class="button primary" data-action="pdf">Ergebnis als PDF <span aria-hidden="true">↓</span></button><button class="button secondary" data-action="print">Ergebnis drucken ↗</button><button class="button secondary" data-action="edit">Antworten prüfen ↗</button></div>
    ${!complete?`<div class="note accent"><strong>Unvollständige Angaben – keine abschließende Punktzahl.</strong><p>Für jedes offene Kriterium berücksichtigt der Rechner den niedrigsten und höchsten zulässigen Wert. Die Modulgrenzen und die gemeinsame Gewichtung von Modul 2 und 3 werden auf beide Grenzen angewendet. ${r.total.min===r.total.max?'Beide Grenzen fallen derzeit zusammen; trotzdem sind Angaben offen und müssen für eine vollständige Einschätzung geklärt werden.':''}</p><details><summary>${r.missingIds.length} offene Fragen ergänzen</summary><ul class="uncertain-list">${r.missingIds.map(id=>`<li><button data-question="${id}">${id} · ${esc(QUESTIONS.find(q=>q.id===id).title)} →</button></li>`).join('')}</ul></details></div>`:''}
    ${state.duration!=='yes'?'<div class="note"><strong>Die Dauer des Hilfebedarfs ist noch zu klären.</strong><p>Pflegebedürftigkeit muss voraussichtlich mindestens sechs Monate bestehen. Die Punktzahl allein begründet keinen Leistungsanspruch. Ein vorübergehender Hilfebedarf kann andere Unterstützungsleistungen auslösen; fragen Sie Ihre Kranken- oder Pflegeversicherung.</p></div>':''}
    <section class="result-section"><h2>So setzt sich Ihr Ergebnis zusammen.</h2><p class="result-text">Einzelpunkte werden über feste Stufen in gewichtete Punkte umgerechnet. Die sechs Balken zeigen jeweils den Anteil am möglichen Gesamtwert von 100 Punkten.</p><div class="result-chart" aria-label="Aufschlüsselung der sechs Module">${r.modules.map(m=>{
      const other=m.id===2?r.modules[2]:m.id===3?r.modules[1]:null,excluded=other&&m.weighted.max<other.weighted.min;
      return `<div class="chart-row"><div class="chart-name">${m.id}. ${esc(moduleNames[m.id-1])}<small>${range(m.raw)} Einzelpunkte${m.id===2||m.id===3?' · gemeinsamer Anteil':''}${excluded?' · nicht zusätzlich addiert':''}</small></div><div class="chart-track" aria-hidden="true"><div class="chart-bar maximum" style="width:${m.weighted.max}%"></div><div class="chart-bar ${excluded?'excluded':''}" style="width:${m.weighted.min}%"></div></div><div class="chart-value">${range(m.weighted)} <span style="color:#666">/ ${m.maxWeight}</span></div></div>`;
    }).join('')}</div><p class="chart-legend">${!complete?'Kräftiger Balken: Untergrenze. Heller Balken: Obergrenze. ':''}Maximaler Modulwert steht rechts. Modul 2 und 3 zählen zusammen höchstens 15 Punkte.</p><div class="math-line"><strong>Ihr Gesamtwert</strong><br>${range(r.modules[0].weighted)} + max(${range(r.modules[1].weighted)}; ${range(r.modules[2].weighted)}) + ${range(r.modules[3].weighted)} + ${range(r.modules[4].weighted)} + ${range(r.modules[5].weighted)} = ${range(r.total)} Punkte</div><p class="result-text">Aus Modul 2 und 3 wird ausschließlich der höhere gewichtete Wert übernommen. ${biggest.weighted.min>0?`Den größten gesicherten Einzelbeitrag außerhalb dieser gemeinsamen Gruppe liefert „${esc(moduleNames[biggest.id-1])}“ mit ${fmt(biggest.weighted.min)} gewichteten Punkten.`:'Auch ein niedriger Gesamtwert kann mit spürbarem Unterstützungsbedarf im Alltag verbunden sein.'}</p></section>
    <section class="result-section result-details"><h2>Der Rechenweg im Detail.</h2>${r.modules.map(m=>`<details><summary>Modul ${m.id}: ${esc(m.title)} · ${range(m.raw)} → ${range(m.weighted)} Punkte</summary><div class="details-body"><p>${explanation(m.id)}</p>${m.id===5?`<div class="table-wrap"><table><caption>Zwischenschritte in Modul 5; Durchschnitt auf vier Nachkommastellen</caption><thead><tr><th>Gruppe</th><th>Bekannte Häufigkeit</th><th>Gruppenpunkte</th></tr></thead><tbody>${r.details.module5.groups.map(g=>`<tr><td>${esc(g.id)}</td><td>${g.dayAverage!==undefined?`${fmt(g.dayAverage)} / Tag`:g.frequencyPoints!==undefined?`${fmt(g.frequencyPoints)} Rechenpunkte`:'Selbstständigkeit'}${!g.complete?' · Angaben offen':''}</td><td>${range(g.raw)}</td></tr>`).join('')}</tbody></table></div>`:''}<div class="table-wrap"><table><thead><tr><th scope="col">Kriterium</th><th scope="col">Ihre Angabe</th></tr></thead><tbody>${QUESTIONS.filter(q=>q.module===m.id).map(q=>`<tr><td>${q.id} ${esc(q.title)}</td><td>${esc(answerText(q,state.answers[q.id]))}</td></tr>`).join('')}</tbody></table></div><button class="button secondary small" data-module="${m.id}">Modul bearbeiten →</button></div></details>`).join('')}<p class="section-footnote"><a href="#/quellen">Vollständige Umrechnungstabellen und Quellen</a></p></section>
    <section class="result-section"><h2>Was Sie jetzt tun können.</h2><div class="next-steps"><div class="next-step"><span>01 / ANTRAG</span><h3>${r.grade.max===0?'Hilfebedarf besprechen.':'Pflegegrad beantragen.'}</h3><p>${r.grade.max===0?'Besprechen Sie anhaltende Einschränkungen mit einer Pflegeberatungsstelle. Auch unterhalb der rechnerischen Grenze kann ein Antrag oder eine andere Hilfe sinnvoll sein.':'Stellen Sie den Antrag direkt bei Ihrer Pflegeversicherung. Ein formloser Antrag kann den ersten Schritt erleichtern.'}</p><a class="text-link" href="#/ratgeber">Zum Antrag & Muster →</a></div><div class="next-step"><span>02 / VORBEREITUNG</span><h3>Den Alltag dokumentieren.</h3><p>Halten Sie fest, wann und wobei Hilfe nötig ist. Legen Sie Medikamentenplan und Berichte bereit. Eine vertraute Person kann beim Termin dabei sein.</p><a class="text-link" href="#/ratgeber">Zur Vorbereitung →</a></div><div class="next-step"><span>03 / BERATUNG</span><h3>Unterstützung nutzen.</h3><p>Ihre Pflegeversicherung oder ein Pflegestützpunkt kann Sie beraten. Bei bestehendem Pflegegrad und gewachsenem Hilfebedarf kommt ein Höherstufungsantrag infrage.</p><a class="text-link" href="#/faq">Weitere Fragen klären →</a></div></div></section>
    <div class="note"><strong>Besondere Bedarfskonstellationen</strong><p>In besonderen Fällen ist Pflegegrad 5 auch unter 90 Punkten möglich. Dazu gehört die in den Richtlinien konkretisierte Gebrauchsunfähigkeit beider Arme und beider Beine. Dieser Rechner entscheidet darüber nicht. Lassen Sie eine solche Situation ausdrücklich im Rahmen der Begutachtung prüfen.</p></div><p class="disclaimer">${disclaimer}</p><p class="section-footnote">Ein kostenloser Informationsservice von Caro Alltagsbegleitung in Tübingen. Der Selbstcheck ist unabhängig von einer Kontaktaufnahme nutzbar. <a href="#/reform">Geplante Reform 2027: gesonderte Informationen</a></p><button class="reset-link" data-action="reset">Antworten löschen und neu beginnen</button></div>`;
}
